.pilloway-contact-page { box-sizing: border-box; max-width: 1120px; margin-inline: auto; padding: 0 24px 64px; }
.pilloway-contact-lead { max-width: 860px; margin: 0 0 32px; color: #46565a; font-size: clamp(1.15rem, 2vw, 1.4rem); line-height: 1.55; }
.pilloway-contact-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 20px; align-items: stretch; }
.pilloway-contact-card { box-sizing: border-box; min-width: 0; padding: clamp(22px, 3vw, 32px); border: 1px solid #dce7e5; border-radius: 18px; background: #f7faf9; }
.pilloway-contact-card h2 { margin: 0 0 14px; color: #173236; font-size: clamp(1.3rem, 2.3vw, 1.65rem); line-height: 1.2; }
.pilloway-contact-card p { margin: 0 0 12px; color: #445357; line-height: 1.6; overflow-wrap: anywhere; }
.pilloway-contact-card p:last-child { margin-bottom: 0; }
.pilloway-contact-kicker { margin-bottom: 10px !important; color: #117e80 !important; font-size: .78rem; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; }
.pilloway-contact-card a:not(.pilloway-contact-button) { color: #0d7778; font-weight: 600; text-decoration-thickness: 1px; text-underline-offset: 3px; }
.pilloway-contact-actions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 18px; }
.pilloway-contact-button { display: inline-flex; min-height: 44px; align-items: center; justify-content: center; box-sizing: border-box; padding: 10px 18px; border: 1px solid #117e80; border-radius: 999px; background: #117e80; color: #fff !important; font-size: 1rem; font-weight: 650; line-height: 1.2; text-align: center; text-decoration: none; transition: background-color .18s ease, border-color .18s ease; }
.pilloway-contact-button:hover { border-color: #0d6869; background: #0d6869; }
.pilloway-contact-button:focus-visible { outline: 3px solid #bde87a; outline-offset: 3px; }
.pilloway-contact-hours { margin-top: 14px !important; padding-top: 14px; border-top: 1px solid #dce7e5; font-size: .98rem; }
@media (max-width: 781px) { .pilloway-contact-page { padding: 0 18px 48px; } .pilloway-contact-grid { grid-template-columns: 1fr; gap: 14px; } .pilloway-contact-card { padding: 22px; } .pilloway-contact-actions { align-items: stretch; } .pilloway-contact-button { width: 100%; } }
@media (min-width: 782px) { header .wp-block-navigation { margin-inline-end: clamp(10px, 1vw, 16px); } }
.pilloway-reviews-page { box-sizing: border-box; max-width: 1180px; margin-inline: auto; padding: 0 24px 64px; color: #243538; }
.pilloway-reviews-intro { max-width: 850px; margin: 0 0 24px; color: #46565a; font-size: clamp(1.1rem, 2vw, 1.3rem); line-height: 1.55; }
