.pilloway-reviews-score { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px; color: #173236; }
.pilloway-reviews-score strong { font-size: clamp(2.5rem, 6vw, 4rem); line-height: 1; }
.pilloway-reviews-score span { color: #526366; font-size: 1.1rem; }
.pilloway-reviews-score small { flex-basis: 100%; color: #526366; font-size: .95rem; line-height: 1.4; }
.pilloway-reviews-breakdown { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 8px; }
.pilloway-reviews-breakdown span { display: block; padding: 10px 8px; border: 1px solid #d5e4e1; border-radius: 10px; background: #fff; color: #34474a; font-size: .88rem; text-align: center; }
.pilloway-reviews-note { margin: 0 0 22px; color: #526366; line-height: 1.55; }
.pilloway-review-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; align-items: stretch; }
.pilloway-review-card { box-sizing: border-box; min-width: 0; padding: 16px; border: 1px solid #dce7e5; border-radius: 14px; background: #fff; box-shadow: 0 3px 12px rgb(23 50 54 / 5%); }
.pilloway-review-header { display: flex; flex-wrap: wrap; align-items: flex-start; justify-content: space-between; gap: 6px 10px; margin-bottom: 8px; }
.pilloway-review-author { color: #173236; font-size: 1.05rem; font-weight: 700; }
.pilloway-review-date { display: block; margin-top: 3px; color: #738184; font-size: .88rem; }

.pilloway-review-stars { margin: 3px 0 9px; color: #117e80; font-size: 1.05rem; letter-spacing: .08em; line-height: 1; }
.pilloway-review-body { margin: 0; color: #354649; font-size: .96rem; line-height: 1.5; overflow-wrap: anywhere; }
.pilloway-review-tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.pilloway-review-tags span { display: inline-flex; gap: 5px; align-items: center; padding: 5px 8px; border-radius: 999px; background: #edf7f5; color: #34565a; font-size: .78rem; line-height: 1.3; }
.pilloway-review-products { margin-top: 10px; padding-top: 10px; border-top: 1px solid #e4ecea; color: #526366; font-size: .88rem; line-height: 1.45; }
.pilloway-review-products ul { margin: 5px 0 0; padding-inline-start: 18px; }
.pilloway-review-products li { margin: 3px 0; overflow-wrap: anywhere; }
.pilloway-review-products a { color: #0d7778; font-weight: 650; text-decoration-thickness: 1px; text-underline-offset: 3px; }
.pilloway-review-reply { margin-top: 14px; padding: 12px 14px; border-left: 3px solid #117e80; border-radius: 0 10px 10px 0; background: #f2f7f6; color: #445357; font-size: .92rem; line-height: 1.55; }
.pilloway-review-reply strong { display: block; margin-bottom: 5px; color: #173236; }
.pilloway-review-reply p { margin: 0; }

.pilloway-reviews-archive { margin-top: 28px; border: 1px solid #dce7e5; border-radius: 14px; background: #f7faf9; }
.pilloway-reviews-archive > summary { padding: 16px 20px; color: #173236; cursor: pointer; font-weight: 700; }
.pilloway-reviews-archive[open] > .pilloway-review-grid { padding: 0 14px 14px; }
@media (max-width: 781px) { .pilloway-reviews-page { padding: 0 18px 48px; } .pilloway-reviews-summary { grid-template-columns: 1fr; gap: 16px; } .pilloway-reviews-breakdown { grid-template-columns: repeat(3, minmax(0, 1fr)); } .pilloway-review-grid { grid-template-columns: 1fr; gap: 10px; } .pilloway-review-card { padding: 14px; } .pilloway-reviews-archive[open] > .pilloway-review-grid { padding: 0 10px 10px; } }
@media (min-width: 782px) and (max-width: 1023px) { .pilloway-review-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; } }.wp-block-navigation li.pilloway-nav-categories > details > summary { align-items: center; cursor: pointer; display: flex; justify-content: space-between; list-style: none; }
.wp-block-navigation li.pilloway-nav-categories > details > summary::after { border-bottom: 1.5px solid currentColor; border-right: 1.5px solid currentColor; content: ""; flex: 0 0 7px; height: 7px; margin-left: 12px; transform: rotate(45deg); transition: transform .18s ease; width: 7px; }
.wp-block-navigation li.pilloway-nav-categories > details[open] > summary::after { transform: rotate(225deg); }
@media (min-width: 782px) {
