 .wp-block-navigation li.pilloway-nav-categories:hover > details > .pilloway-nav-categories-list, .wp-block-navigation li.pilloway-nav-categories:focus-within > details > .pilloway-nav-categories-list, .wp-block-navigation li.pilloway-nav-categories > details[open] > .pilloway-nav-categories-list { opacity: 1; pointer-events: auto; visibility: visible; }
}
@media (max-width: 781px) {
