 .wp-block-navigation__responsive-container.is-menu-open li.pilloway-nav-categories > details > summary { padding: 8px 10px; }
 .wp-block-navigation__responsive-container.is-menu-open li.pilloway-nav-categories > details > .pilloway-nav-categories-list { background: transparent; border: 0; border-left: 2px solid #d7e8e5; border-radius: 0; box-shadow: none; display: none !important; grid-template-columns: 1fr; left: auto; margin: 8px 0 12px 6px !important; max-height: none; min-width: 0 !important; opacity: 1; overflow: visible; padding: 0 0 0 14px !important; pointer-events: auto; position: static; right: auto; top: auto; visibility: visible; width: 100% !important; }
 .wp-block-navigation__responsive-container.is-menu-open li.pilloway-nav-categories > details[open] > .pilloway-nav-categories-list { display: flex !important; flex-direction: column; }
