.pilloway-certificates-section { box-sizing: border-box; padding: clamp(22px, 4vw, 52px); border: 1px solid #dce9e6; border-radius: 28px; background: linear-gradient(135deg, #f7faf9 0%, #eef7f5 100%); }
.pilloway-certificates-section .pilloway-certificates-kicker { margin: 0 0 10px; color: #117e80; font-size: .76rem; font-weight: 800; letter-spacing: .16em; line-height: 1.4; text-transform: uppercase; }
.pilloway-certificates-section .pilloway-certificates-section__title { margin: 0 0 12px; color: #193337; font-size: clamp(1.55rem, 3vw, 2.35rem); font-weight: 750; letter-spacing: -.035em; line-height: 1.12; }
.pilloway-certificates-section .pilloway-certificates-description { max-width: 720px; margin: 0 0 clamp(22px, 3vw, 32px); color: #667779; font-size: 1rem; line-height: 1.65; }
.pilloway-certificates-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: clamp(16px, 2.4vw, 26px); align-items: stretch; }
.pilloway-certificate-card { min-width: 0; overflow: hidden; display: flex; flex-direction: column; border: 1px solid #dfe9e7; border-radius: 20px; background: #fff; box-shadow: 0 12px 32px rgba(26, 59, 61, .07); }
