.pilloway-certificate-card__body { display: flex; flex: 1; flex-direction: column; align-items: flex-start; padding: clamp(18px, 2.5vw, 26px); }
.pilloway-certificate-card__number { margin: 0 0 9px; color: #117e80; font-size: .75rem; font-weight: 800; letter-spacing: .12em; }
.pilloway-certificate-card__title { margin: 0 0 10px; color: #193337; font-size: clamp(1.08rem, 1.6vw, 1.3rem); font-weight: 750; line-height: 1.35; }
