@media (max-width: 781px) { .wp-block-navigation__responsive-container.is-menu-open .pilloway-nav-categories > details:not([open]) > .pilloway-nav-categories-list { display: none !important; } .wp-block-navigation__responsive-container.is-menu-open .pilloway-nav-categories > details[open] > .pilloway-nav-categories-list { display: flex !important; } }

/* Shared page width and titles */
/* Let full-width post content escape the theme's inner padding exactly once. */
body:has(.pilloway-palette-page) .wp-block-post-content.alignfull,
body:has(.pilloway-blog-page) .wp-block-post-content.alignfull {
 box-sizing: border-box;
 max-width: none !important;
 width: auto !important;
 margin-left: calc(var(--wp--style--root--padding-left) * -1) !important;
 margin-right: calc(var(--wp--style--root--padding-right) * -1) !important;
}
body:has(.pilloway-palette-page) .wp-block-post-content:not(.alignfull),
body:has(.pilloway-blog-page) .wp-block-post-content:not(.alignfull) { max-width: none !important; width: 100%; margin-inline: 0 !important; }
.pilloway-palette-page, .pilloway-blog-page { box-sizing: border-box; width: min(1200px, calc(100% - 48px)); max-width: 1200px !important; margin: 0 auto; padding: 0 0 clamp(48px, 7vw, 80px); }
body:has(.pilloway-palette-page) main > .wp-block-group > .wp-block-post-title,
body:has(.pilloway-blog-page) main > .wp-block-group > .wp-block-post-title { box-sizing: border-box; width: min(1200px, calc(100% - 48px)); max-width: 1200px; margin: clamp(28px, 5vw, 52px) auto 18px !important; color: #173236; font-size: clamp(2.25rem, 4.6vw, 3.65rem); font-weight: 700; letter-spacing: -.045em; line-height: 1.05; }

/* Pillowcase color gallery */
.pilloway-palette-hero { position: relative; overflow: hidden; box-sizing: border-box; margin: 0 0 clamp(32px, 5vw, 54px); padding: clamp(28px, 5vw, 58px); border: 1px solid rgba(255,255,255,.2); border-radius: 26px; background: radial-gradient(circle at 90% 20%, rgba(189,232,122,.24), transparent 32%), linear-gradient(125deg, #0e686b, #117e80 58%, #168c87); box-shadow: 0 18px 44px rgba(15,92,94,.16); }
.pilloway-palette-kicker { margin: 0 0 12px !important; color: #d3f08f; font-size: .78rem; font-weight: 750; letter-spacing: .16em; line-height: 1.3; text-transform: uppercase; }
.pilloway-palette-intro { max-width: 820px; margin: 0 !important; color: #fff; font-size: clamp(1.12rem, 2vw, 1.42rem); line-height: 1.58; }
.pilloway-palette-gallery__heading { display: flex; align-items: end; justify-content: space-between; gap: 20px; margin: 0 0 22px; }
.pilloway-palette-gallery__heading h2 { margin: 0; color: #173236; font-size: clamp(1.55rem, 3vw, 2.2rem); letter-spacing: -.035em; line-height: 1.12; }
.pilloway-palette-count { flex: 0 0 auto; margin: 0 0 3px !important; color: #117e80; font-size: .76rem; font-weight: 750; letter-spacing: .14em; }
.pilloway-palette-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: clamp(12px, 1.8vw, 20px); align-items: stretch; }
.pilloway-palette-card { min-width: 0; overflow: hidden; border: 1px solid #dce7e5; border-radius: 18px; background: #fff; box-shadow: 0 6px 20px rgba(23,50,54,.045); transition: box-shadow .2s ease, transform .2s ease; }
.pilloway-palette-card:hover { box-shadow: 0 14px 30px rgba(23,50,54,.12); transform: translateY(-3px); }
.pilloway-palette-card__image-link { display: block; overflow: hidden; background: #f6faf9; line-height: 0; }
.pilloway-palette-card__image-link:focus-visible { outline: 3px solid #117e80; outline-offset: -3px; }
.pilloway-palette-card__image { display: block; width: 100%; height: auto; aspect-ratio: 1; object-fit: contain; background: #fff; }
.pilloway-palette-card__body { min-height: 90px; padding: 14px 16px 17px; }
.pilloway-palette-card__number { margin: 0 0 5px !important; color: #117e80; font-size: .72rem; font-weight: 750; letter-spacing: .12em; text-transform: uppercase; }
.pilloway-palette-card__title { margin: 0 !important; color: #263c3f; font-size: .96rem; font-weight: 650; line-height: 1.4; }
.pilloway-palette-cta { display: flex; align-items: center; justify-content: space-between; gap: 24px; margin-top: clamp(30px, 5vw, 54px); padding: clamp(24px, 4vw, 40px); border-radius: 22px; background: linear-gradient(120deg, #0d686b, #138b87); color: #fff; }
.pilloway-palette-cta__eyebrow { margin: 0 0 8px !important; color: #d3f08f; font-size: .74rem; font-weight: 750; letter-spacing: .15em; text-transform: uppercase; }
.pilloway-palette-cta__text { max-width: 680px; margin: 0 !important; color: #fff; font-size: clamp(1.15rem, 2.4vw, 1.55rem); font-weight: 650; line-height: 1.35; }
.pilloway-palette-cta__button { display: inline-flex; min-height: 48px; flex: 0 0 auto; align-items: center; justify-content: center; box-sizing: border-box; padding: 12px 22px; border: 0; border-radius: 999px; background: #c9ed83; color: #173236 !important; font-weight: 750; line-height: 1.2; text-align: center; text-decoration: none; transition: background .18s ease, transform .18s ease; }
.pilloway-palette-cta__button:hover { background: #d7f49c; transform: translateY(-1px); }
.pilloway-palette-cta__button:focus-visible { outline: 3px solid #fff; outline-offset: 3px; }

/* Pilloway editorial blog */
.pilloway-blog-hero { position: relative; overflow: hidden; box-sizing: border-box; margin: 0 0 clamp(32px, 5vw, 52px); padding: clamp(30px, 5.5vw, 64px); border-radius: 26px; background: radial-gradient(circle at 90% 12%, rgba(189,232,122,.23), transparent 30%), linear-gradient(125deg, #0e686b, #117e80 58%, #168c87); box-shadow: 0 18px 44px rgba(15,92,94,.16); }
.pilloway-blog-kicker { margin: 0 0 12px !important; color: #d3f08f; font-size: .78rem; font-weight: 750; letter-spacing: .16em; line-height: 1.3; text-transform: uppercase; }
.pilloway-blog-intro { max-width: 820px; margin: 0 !important; color: #fff; font-size: clamp(1.12rem, 2vw, 1.42rem); line-height: 1.58; }
