.pilloway-blog-query .wp-block-post { display: flex; min-width: 0; flex-direction: column; overflow: hidden; border: 1px solid #dce7e5; border-radius: 18px; background: #fff; box-shadow: 0 6px 20px rgba(23,50,54,.05); transition: box-shadow .2s ease, transform .2s ease; }
.pilloway-blog-query .wp-block-post:hover { box-shadow: 0 14px 30px rgba(23,50,54,.12); transform: translateY(-3px); }
.pilloway-blog-query .wp-block-post-featured-image { width: 100%; aspect-ratio: 3 / 2; overflow: hidden; margin: 0 0 16px; background: #eef6f4; }
.pilloway-blog-query .wp-block-post-featured-image a { display: block; width: 100%; height: 100%; }
.pilloway-blog-query .wp-block-post-featured-image img { display: block; width: 100%; height: 100%; object-fit: cover; }
.pilloway-blog-card__category { margin: 0 20px 8px !important; color: #117e80; font-size: .72rem; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; }
.pilloway-blog-card__category a { color: inherit; text-decoration: none; }
.pilloway-blog-card__date { margin: 0 20px 8px !important; color: #738184; font-size: .84rem; }
.pilloway-blog-card__title { margin: 0 20px 10px !important; color: #173236; font-size: clamp(1.15rem, 1.8vw, 1.4rem); font-weight: 700; letter-spacing: -.02em; line-height: 1.27; }
.pilloway-blog-card__title a { color: inherit; text-decoration: none; }
.pilloway-blog-card__title a:hover { color: #0d7778; }
.pilloway-blog-query .wp-block-post-excerpt { margin: 0 20px 22px !important; color: #526164; font-size: .98rem; line-height: 1.6; }
.pilloway-blog-query .wp-block-post-excerpt__more-link { color: #0d7778; font-weight: 700; text-decoration-thickness: 1px; text-underline-offset: 3px; }
.pilloway-blog-empty { box-sizing: border-box; max-width: 900px !important; margin: 0 auto; padding: clamp(28px, 5vw, 54px); border: 1px solid #dce7e5; border-radius: 24px; background: linear-gradient(140deg, #eef8f5, #f7faee); text-align: center; }
.pilloway-blog-empty__eyebrow { margin: 0 0 10px !important; color: #117e80; font-size: .75rem; font-weight: 750; letter-spacing: .15em; text-transform: uppercase; }
.pilloway-blog-empty__title { margin: 0 0 12px !important; color: #173236; font-size: clamp(1.6rem, 3.4vw, 2.35rem); letter-spacing: -.035em; line-height: 1.12; }
.pilloway-blog-empty__text { max-width: 650px; margin: 0 auto 22px !important; color: #4f5f62; font-size: clamp(1rem, 1.8vw, 1.15rem); line-height: 1.6; }
.pilloway-blog-empty__actions { justify-content: center; margin: 0 !important; }
.pilloway-blog-empty__button .wp-block-button__link { display: inline-flex; min-height: 48px; align-items: center; justify-content: center; box-sizing: border-box; padding: 12px 24px; border: 0; border-radius: 999px; background: #117e80; color: #fff; font-weight: 750; line-height: 1.2; text-decoration: none; transition: background .18s ease, transform .18s ease; }
.pilloway-blog-empty__button .wp-block-button__link:hover { background: #0d686b; transform: translateY(-1px); }
.pilloway-blog-empty__button .wp-block-button__link:focus-visible { outline: 3px solid #c9ed83; outline-offset: 3px; }
.pilloway-blog-query .wp-block-query-pagination { margin-top: 32px; color: #173236; }
.pilloway-blog-query .wp-block-query-pagination a { color: #0d7778; font-weight: 700; text-decoration-thickness: 1px; text-underline-offset: 3px; }
@media (max-width: 1024px) {
 .pilloway-palette-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
 .pilloway-blog-query .wp-block-post-template { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 781px) {
 .pilloway-palette-page, .pilloway-blog-page { width: calc(100% - 32px); padding-bottom: 52px; }
 body:has(.pilloway-palette-page) main > .wp-block-group > .wp-block-post-title,
 body:has(.pilloway-blog-page) main > .wp-block-group > .wp-block-post-title { width: calc(100% - 32px); margin: 28px auto 16px !important; font-size: clamp(2rem, 9vw, 2.75rem); }
 .pilloway-palette-hero, .pilloway-blog-hero { margin-bottom: 30px; padding: 28px 24px; border-radius: 20px; }
 .pilloway-palette-gallery__heading { align-items: start; flex-direction: column; gap: 8px; margin-bottom: 16px; }
 .pilloway-palette-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
 .pilloway-palette-card { border-radius: 14px; }
 .pilloway-palette-card__body { min-height: 74px; padding: 11px 12px 13px; }
 .pilloway-palette-card__title { font-size: .88rem; }
 .pilloway-palette-cta { align-items: stretch; flex-direction: column; gap: 18px; margin-top: 28px; padding: 24px; border-radius: 20px; }
 .pilloway-palette-cta__button { width: 100%; }
 .pilloway-blog-query .wp-block-post-template { grid-template-columns: 1fr; gap: 16px; }
 .pilloway-blog-query .wp-block-post { border-radius: 16px; }
 .pilloway-blog-card__category, .pilloway-blog-card__date { margin-inline: 16px !important; }
 .pilloway-blog-card__title { margin-inline: 16px !important; }
 .pilloway-blog-query .wp-block-post-excerpt { margin-inline: 16px !important; }
 .pilloway-blog-empty { padding: 28px 22px; border-radius: 20px; }
}


/* Final responsive layout refinements for palette and blog pages */
body:has(.pilloway-palette-page) main, body:has(.pilloway-blog-page) main { margin-top: 0 !important; }
body:has(.pilloway-palette-page) main > .wp-block-group.alignfull, body:has(.pilloway-blog-page) main > .wp-block-group.alignfull { padding-top: clamp(18px, 3vw, 30px) !important; padding-bottom: 24px !important; }
body:has(.pilloway-palette-page) main > .wp-block-group > .wp-block-post-title, body:has(.pilloway-blog-page) main > .wp-block-group > .wp-block-post-title { margin-top: 0 !important; }
.pilloway-blog-page > .pilloway-blog-hero, .pilloway-blog-page > .pilloway-blog-query { width: 100% !important; max-width: none !important; margin-inline: 0 !important; }
.pilloway-blog-empty { width: min(100%, 900px) !important; margin-inline: auto !important; }
@media (max-width: 520px) { .pilloway-palette-grid { grid-template-columns: 1fr; } }


/* Keep the catalog result count and sorting control inside narrow phone widths. */
@media (max-width: 520px) {
 main > .wp-block-group.alignwide.is-layout-flex:has(.wc-block-catalog-sorting) {
  flex-wrap: wrap !important;
  justify-content: flex-start !important;
  row-gap: 12px;
 }
 main .wc-block-catalog-sorting {
  flex: 1 1 100%;
  box-sizing: border-box;
  width: 100%;
  max-width: 100%;
 }
 main .wc-block-catalog-sorting .woocommerce-ordering {
  width: 100%;
  max-width: 100%;
  margin: 0;
 }
 main .wc-block-catalog-sorting .orderby {
  display: block;
  box-sizing: border-box;
  width: 100%;
  max-width: 100%;
  min-width: 0;
 }
}
/* Pilloway launch design layer: styles only */
:root {
 --pilloway-ink:#173236;
 --pilloway-teal:#117e80;
