 --pilloway-lime:#c9ed83;
 --pilloway-muted:#657477;
 --pilloway-line:#dce7e5;
 --pilloway-soft:#f4f8f7;
 --pilloway-shadow:0 8px 24px rgba(23,50,54,.07);
}

/* Product catalog, category and sale archives */
body.post-type-archive-product main>.wp-block-query-title,
body.tax-product_cat main>.wp-block-query-title,
body.tax-product_tag main>.wp-block-query-title {
