/* Search results: align the form and result cards to the same centered content width */
body.search .wp-block-post-template {
  box-sizing: border-box;
  width: min(1200px, calc(100% - var(--wp--style--root--padding-left, 24px) - var(--wp--style--root--padding-right, 24px)));
  margin-inline: auto;
}
body.search .wp-block-post-title {
  font-size: clamp(1.1rem, 4.5vw, 1.25rem) !important;
}
@media (max-width: 781px) {
  body.search .wp-block-post-template {
    width: calc(100% - var(--wp--style--root--padding-left, 16px) - var(--wp--style--root--padding-right, 16px));
    margin-inline: auto;
  }
  body.search .wp-block-search__inside-wrapper {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 10px;
  }
  body.search .wp-block-search__input,
